        (b) =>
          b.title.toLowerCase().includes(query) ||
          b.url?.toLowerCase().includes(query) ||
          b.note?.toLowerCase().includes(query)
      )
    }

    // Sort
    result.sort((a, b) => {
      switch (sortBy) {
        case 'newest':
          return new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
        case 'oldest':
          return new Date(a.created_at).getTime() - new Date(b.created_at).getTime()
        case 'title-az':
          return a.title.localeCompare(b.title)
        case 'title-za':
          return b.title.localeCompare(a.title)
        default:
          return 0
      }
    })

    return result
  }, [initialBookmarks, searchQuery, sortBy])

  return (
    <div className="space-y-8">
      {/* Controls */}
      <div className="flex flex-col sm:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-zinc-400" />
          <input
            type="text"
            placeholder="Search links..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-12 pr-4 py-3 bg-white border border-zinc-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all shadow-sm"
          />
        </div>

        <div className="flex items-center gap-2 bg-white px-4 py-2 rounded-2xl border border-zinc-200 shadow-sm">
          <SortAsc className="h-5 w-5 text-zinc-400" />
          <select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value as SortOption)}
            className="bg-transparent border-none outline-none text-zinc-600 font-medium cursor-pointer text-sm"
